  "category" TEXT,
  "summary_ar" TEXT,
  "summary_en" TEXT,
  "sections" TEXT,
  "sources" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE IF NOT EXISTS "travel_categories" (
  "id" TEXT PRIMARY KEY,
